import socket,json,pathlib
rows=[]
for h in ['example.com','postgres','kong']:
 try:rows.append({'host':h,'addresses':sorted({r[4][0] for r in socket.getaddrinfo(h,443)})})
 except socket.gaierror as e:rows.append({'host':h,'errno':e.errno,'message':str(e)})
print(json.dumps({'resolv_conf':pathlib.Path('/etc/resolv.conf').read_text(),'queries':rows}))
